package ru.neverland.archaeology.restoration;

import java.util.*;import java.util.concurrent.*;import java.nio.charset.StandardCharsets;
import org.bukkit.*;import org.bukkit.block.BrushableBlock;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.BlockDispenseLootEvent;import org.bukkit.inventory.ItemStack;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.scheduler.BukkitTask;
import ru.neverland.archaeology.service.*;import ru.neverland.core.*;
import static ru.neverland.archaeology.restoration.RestorationBook.*;

/** Optional fragment layer. Only registered brushed blocks create source receipts; legacy loot is never altered. */
public final class RestorationService implements Listener {
    private record Finding(UUID source,String origin,UUID player,String name,long at,Recipe recipe){}
    private final JavaPlugin plugin;private final ArchaeologyRegistry registry;private final ArchaeologyRepository legacy;private final ArtifactService artifacts;private final RestorationRepository repository;private final RestorationAudit audit;
    private RestorationSettings settings;private RestorationItems items;private RestorationTransfer transfer;private BukkitTask task;private boolean closing;private String unavailable="Реставрация ещё загружается";private final ArrayDeque<Finding> queue=new ArrayDeque<>();private final Set<UUID> queued=new HashSet<>();private long warningAt;
    private final NamespacedKey siteKey,oldSiteKey;
    public RestorationService(JavaPlugin plugin,ArchaeologyRegistry registry,ArchaeologyRepository legacy,ArtifactService artifacts){this.plugin=plugin;this.registry=registry;this.legacy=legacy;this.artifacts=artifacts;siteKey=new NamespacedKey(plugin,"site_id");oldSiteKey=NamespacedKey.fromString("townyarchaeology:site_id");repository=new RestorationRepository(plugin.getDataFolder().toPath().resolve("restoration.yml"));audit=new RestorationAudit(plugin);
        try{settings=RestorationSettings.read(plugin.getConfig());repository.load();items=new RestorationItems(plugin,registry);transfer=new RestorationTransfer(plugin,repository,items,artifacts,new PlayerSaveEvidence(plugin),this::changed);unavailable="";}catch(Exception error){plugin.getLogger().log(java.util.logging.Level.WARNING,"Реставрация приостановлена; прежние раскопки и музей продолжают работать",error);unavailable="Реставрация требует проверки администратором; прежние артефакты доступны.";}
        ModuleShutdown.register(plugin,this::prepareClose);task=SuiteScheduler.get().runTaskTimer(plugin,this::pulse,20,20);
    }
    public RestorationRepository repository(){return repository;}public RestorationTransfer transfer(){requireReady();return transfer;}public ArchaeologyRegistry registry(){return registry;}
    public boolean ready(){return !closing&&transfer!=null&&settings!=null&&settings.enabled()&&repository.writable()&&plugin.isEnabled()&&!SuiteState.frozen(plugin.getName());}
    public String availability(){if(!unavailable.isEmpty())return unavailable;if(settings==null||!settings.enabled())return "Реставрация отключена администратором. Находки и начатые операции сохранены.";if(!repository.writable())return "Журнал реставрации недоступен; предметы не перемещаются.";return "Реставрация временно приостановлена.";}
    public void requireReady(){if(!ready())throw new IllegalStateException(availability());}
    public void reloadSettings(){try{var next=RestorationSettings.read(plugin.getConfig());settings=next;}catch(RuntimeException error){plugin.getLogger().warning("Настройки реставрации не применены: "+error.getMessage());}}
    private void changed(){/* The timer repairs audit from the acknowledged immutable book. */}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void brushed(BlockDispenseLootEvent event){
        Player player=event.getPlayer();if(closing||transfer==null||SuiteState.frozen(plugin.getName())||player==null||!player.hasPermission("townyarchaeology.use")||!player.hasPermission("townyarchaeology.restore"))return;
        var block=event.getBlock();if(!(block.getState() instanceof BrushableBlock brush))return;String raw=brush.getPersistentDataContainer().get(siteKey,PersistentDataType.STRING);if(raw==null&&oldSiteKey!=null)raw=brush.getPersistentDataContainer().get(oldSiteKey,PersistentDataType.STRING);if(raw==null)return;final UUID site;try{site=UUID.fromString(raw);}catch(IllegalArgumentException invalid){return;}
        UUID world=block.getWorld().getUID();int x=block.getX(),y=block.getY(),z=block.getZ();UUID playerId=player.getUniqueId();String name=player.getName();long at=System.currentTimeMillis();List<ItemStack> loot=event.getDispensedLoot().stream().filter(Objects::nonNull).limit(16).map(ItemStack::clone).toList();
        // All Bukkit reads above belong to the brush event's region. Deferred work reads metadata only.
        Runnable capture=()->consider(site,world,x,y,z,playerId,name,at,loot);if(!SuiteState.tryRun("Archaeology brushed receipt",capture))SuiteScheduler.get().runTask(plugin,capture);
    }
    private void consider(UUID siteId,UUID world,int x,int y,int z,UUID player,String name,long at,List<ItemStack> loot){if(!ready())return;var site=legacy.sites().get(siteId);if(site==null||site.completed()||!site.worldId().equals(world)||!site.blocks().contains(DigKey(x,y,z)))return;var definition=registry.site(site.type());if(definition==null)return;
        String artifact=null;for(var item:loot){var identity=artifacts.identity(item);if(identity!=null&&identity.valid()&&definition.artifactWeights().getOrDefault(identity.artifactId(),0)>0){artifact=identity.artifactId();break;}}if(artifact==null)return;var entry=registry.artifact(artifact);if(entry==null)return;String origin="site:"+siteId+"|world:"+world+"|block:"+x+","+y+","+z;UUID source=UUID.nameUUIDFromBytes(origin.getBytes(StandardCharsets.UTF_8));if(repository.state().sources().containsKey(source)||queued.contains(source))return;
        if(queue.size()>=64){warn("Очередь дополнительных фрагментов заполнена. Обычный лут раскопок выдан без изменений.");return;}queue.addLast(new Finding(source,origin,player,name,at,settings.recipe(artifact,entry.rarity())));queued.add(source);
    }
    private static String DigKey(int x,int y,int z){return x+","+y+","+z;}
    private void pulse(){if(closing)return;if(repository.readable())audit.pulse(repository.state());if(!ready()||repository.busy()||transfer.busy())return;transfer.recoverPrepared();if(repository.busy())return;Finding finding=queue.pollFirst();if(finding==null)return;queued.remove(finding.source());var book=repository.state();if(book.sources().containsKey(finding.source()))return;if(book.sources().size()>=MAX_SOURCES||book.fragments().size()>=MAX_FRAGMENTS){warn("Архив фрагментов заполнен; новые дополнительные находки приостановлены. Старые артефакты доступны.");return;}
        boolean receive=book.minted(finding.player(),finding.at())<settings.player24h()&&book.minted(null,finding.at())<settings.server24h()&&book.fragments().values().stream().filter(f->f.finder().equals(finding.player())&&f.phase()==FragmentPhase.MAILBOX).count()<settings.mailbox()&&items.draw(finding.source())<settings.chance();UUID fragmentId=receive?UUID.randomUUID():null;var source=new Source(finding.source(),finding.origin(),finding.player(),finding.name(),finding.at(),fragmentId);var fragment=receive?new Fragment(fragmentId,source.id(),finding.player(),finding.name(),finding.recipe(),items.part(source.id(),finding.recipe().parts()),finding.at(),FragmentPhase.MAILBOX,null):null;
        try{repository.commit(book,book.discover(source,fragment)).whenComplete((saved,error)->{if(error!=null){warn("Не подтверждено сохранение дополнительной находки; обычный лут не менялся.");return;}if(fragment!=null)try(var guard=SuiteState.guard()){if(closing||!plugin.isEnabled())return;Player player=Bukkit.getPlayer(finding.player());if(player!=null)SuiteScheduler.player(plugin,player,p->{if(p.hasPermission("townyarchaeology.use")&&p.hasPermission("townyarchaeology.restore"))p.sendMessage("§eНа раскопках найден фрагмент. Получите его в /archaeology fragments.");});}});}catch(RuntimeException error){warn("Не удалось записать источник фрагмента: "+error.getMessage());}
    }
    public List<TargetedSearch.Hint> search(Player player,String artifact){if(!player.hasPermission("townyarchaeology.use")||!player.hasPermission("townyarchaeology.search"))throw new IllegalArgumentException("У вас нет доступа к поиску раскопок.");if(registry.artifact(artifact)==null)throw new IllegalArgumentException("Такого артефакта нет в каталоге.");var location=player.getLocation();int radius=settings==null?5000:settings.searchRadius();return TargetedSearch.find(artifact,location.getWorld().getUID(),location.getBlockX(),location.getBlockY(),location.getBlockZ(),radius,legacy.sites().values(),registry.sites());}
    private void warn(String message){long now=System.currentTimeMillis();if(now-warningAt>=30000){warningAt=now;plugin.getLogger().warning(message);}}
    public CompletionStage<Void> prepareClose(){try(var guard=SuiteState.guard()){if(task!=null)task.cancel();closing=true;queue.clear();queued.clear();CompletionStage<Void> evidence=transfer==null?CompletableFuture.completedFuture(null):transfer.prepareClose();return evidence.thenCompose(v->repository.prepareClose()).thenCompose(v->audit.closeAsync());}}
    public void awaitClosed(){var stage=prepareClose().toCompletableFuture();if(SuiteState.held()&&!stage.isDone()){stage.whenCompleteAsync((v,e)->{if(e!=null)plugin.getLogger().warning("Незавершённая реставрация сохранена для сверки: "+e);});return;}try{stage.get(10,TimeUnit.SECONDS);}catch(Exception error){plugin.getLogger().log(java.util.logging.Level.WARNING,"Остановка реставрации требует проверки журнала; автоматической повторной выдачи нет",error);}}
}
